mapper.select:
select ID, PRINCIPAL_TYPE, PRINCIPAL_ID, TASK_ID, RESOURCE, ACTION, SCOPE, RESULT, REASON
from AUTHORIZATION_LOG
where ID = #{id} and TASK_ID = #{task_id} and PRINCIPAL_TYPE = 'AGENT' and PRINCIPAL_ID = #{agent_id}

mapper.update:
update AUTHORIZATION_LOG set RESOURCE = #{resource}, ACTION = #{action}, SCOPE = #{scope},
                             RESULT = #{result}, REASON = #{reason}
where ID = #{id} and TASK_ID = #{task_id} and PRINCIPAL_TYPE = 'AGENT' and PRINCIPAL_ID = #{principal_id}
